class Solution:
    def numWays(self, s: str) -> int:
        n = len(s)
        pre = [0] * (n + 1)
        for i, ch in enumerate(s):
            pre[i + 1] = pre[i] + (ch == '1')
        total, ans = pre[n], 0
        for i in range(1, n - 1):
            for j in range(i + 1, n):
                if pre[i] == pre[j] - pre[i] == total - pre[j]:
                    ans += 1
        return ans % (10**9 + 7)

