        cnt++;
        if (cnt === need) a = i;
        else if (cnt === need + 1) b = i;
        else if (cnt === 2 * need) c = i;
        else if (cnt === 2 * need + 1) d = i;
    }
    return ((b - a) * (d - c)) % MOD;
};
